handlers.downloadButtonClick:
function downloadButtonClick()  {
		$("#downloadButton").attr("disabled", "disabled");
		setTimeout(function() {
			$("#downloadButton").removeAttr("disabled");
		}, 5000);

		var tmpDate = new Date();
		var rId = tmpDate.getTime();

	    $.ajax({
	           type: "POST",
	           url: "exportApiRawDataExport",
	           data : {
					ApiKey : $("#apiKeyFilter").val(),
					ApiName : $("#apiNameFilter").val(),
					Hours : $("#durationFilter").val(),
					FromDate :  $("#fromOrderDate").val(),
					ToDate :  $("#toOrderDate").val(),
					HttpRespCodeType :  $("#httpResponseCodeFilter").val(),
					rId : rId
				},
	           success: function(data) {
	               if(data.jsonMessage==null) {
	            	   window.parent.pendingReportSearch('?uuId='+data.reportId);
	               } else {
	            	   window.parent.showAlert(data.jsonMessage);
	               }
	           }
		});
	}

